css_extra:
.tone-light, .tone-panel, .tone-card { --btn-bg:#4F026B; --btn-fg:#FFFFFF; }
.tone-dark { --turn:#E0C4AB; }
section[data-name="Why us"], section[data-name="How it works"], section[data-name="Final CTA"] { --s-bg:#2A003A; --surface:#3B0B4F; --alt:#3B0B4F; background:#2A003A url(assets/stars-faded.png) 50% 0/1440px auto no-repeat; }
.m section[data-name="Why us"], .m section[data-name="How it works"], .m section[data-name="Final CTA"] { background-size:780px auto; }
[data-name="Watermark"] svg { opacity:.08; }
.tick i { background: url(assets/crown-gold.png) center/17px auto no-repeat; border-radius:0; width:22px; }
.tick i svg { display:none; }
.tone-dark .tick i { background-image:url(assets/crown-white.png); }
.tone-dark .card.tone-card .tick i { background-image:url(assets/crown-gold.png); }
.tone-light [data-name="Story"], .tone-light [data-name="Review"], .tone-light [data-name="Situation"] { border:1px solid #E0C4AB; }
[data-name="Service"] { border:1px solid #B0947B; padding:10px 10px 0; border-radius:0 !important; }
[data-name="Team member"] { border:1px solid #B0947B; padding:10px 10px 20px; }
[data-name="Team member"] .h3, [data-name="Team member"] .label { padding-left:6px; }
[data-name="Step"] { border-top:1px solid #E0C4AB !important; }
[data-name="Step"] .price { color:#D4B8D6; }
[data-name="Booking form"] { border:1px solid #E0C4AB; }
[data-name="Story"] > div:last-child > div:first-child { flex-wrap:wrap; gap:6px 12px; }
section[data-name="Meet your dentist"] p { font-family:'Playfair Display', serif; font-style:italic; font-weight:400 !important; }
